import { Injectable, computed, effect, inject, signal } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import {
    AsyncHandler,
    CalendarEvent,
    MINUTES,
    OrganisationService,
    SettingsService,
    i18n,
    notifyError,
    notifySuccess,
} from '@placeos/common';
import {
    GroupEventDetailsModalComponent,
    queryEventsOrThrow,
    removeEvent,
} from '@placeos/events';
import { endOfDay, format, getUnixTime, startOfDay } from 'date-fns';
import { confirmAction, errorText } from '../ui/modal-actions';

export interface GroupEventOptions {
    period: 'week' | 'month';
    date?: number;
    end?: number;
    zone_ids?: string[];
}

@Injectable({
    providedIn: 'root',
})
export class EventStateService extends AsyncHandler {
    private _settings = inject(SettingsService);
    private _org = inject(OrganisationService);
    private _dialog = inject(MatDialog);
    private _router = inject(Router);

    private readonly _poll = signal(0);
    private readonly _changed = signal(0);

    public readonly options = signal<GroupEventOptions>({ period: 'week' });
    public readonly loading = signal<string>('');
    /** Group events of the loaded period, sorted by start time */
    private readonly _events = signal<CalendarEvent[]>([]);
    /**
     * Period of the events request. Changes to the period type or the
     * zones do not change it, so they do not make a new request.
     */
    private readonly _range = computed(
        () => {
            const { date, end } = this.options();
            return { date, end };
        },
        { equal: (a, b) => a.date === b.date && a.end === b.end },
    );
    /** Loaded events in one of the selected zones. No zones selects all. */
    public readonly event_list = computed(() => {
        const zone_ids = this.options().zone_ids || [];
        if (!zone_ids.length) return this._events();
        return this._events().filter((event) =>
            event.resources?.some((space) =>
                (space.zones || []).some((zone) => zone_ids.includes(zone)),
            ),
        );
    });

    /** Events grouped by `yyyy-MM-dd`, each with calendar `offset`/`length` */
    public readonly event_day_map = computed(() => {
        const map: Record<string, any[]> = {};
        for (const event of this.event_list()) {
            const date = format(event.date, 'yyyy-MM-dd');
            if (!map[date]) map[date] = [];
            const start = new Date(event.date);
            map[date].push({
                ...event,
                offset:
                    (start.getHours() * 60 + start.getMinutes()) / (24 * 60),
                length: event.duration / (24 * 60),
            });
        }
        return map;
    });

    constructor() {
        super();
        effect(() => {
            const bld = this._org.active_building();
            const range = this._range();
            this._changed();
            this._poll();
            if (!bld) return;
            this.timeout('load', () => this._load(range), 310);
        });
    }

    private async _load(range: Pick<GroupEventOptions, 'date' | 'end'>) {
        // The events list sets the period range. Wait for it.
        if (!range.date) return;
        this.loading.set(i18n('APP.CONCIERGE.EVENTS_LOADING'));
        try {
            const list = await queryEventsOrThrow({
                period_start: getUnixTime(startOfDay(range.date)),
                period_end: getUnixTime(endOfDay(range.end || range.date)),
                calendars: this.calendar,
            });
            this._events.set(
                list
                    .filter((_) => _.extension_data?.shared_event)
                    .sort((a, b) => a.date - b.date),
            );
        } catch (e) {
            // An empty list with an error, so a failed load does not look like no events
            this._events.set([]);
            notifyError(
                i18n('APP.CONCIERGE.EVENTS_LIST_ERROR', {
                    error: errorText(e),
                }),
            );
        } finally {
            this.loading.set('');
        }
    }

    public changed() {
        this.timeout('changed', () => this._changed.set(Date.now()), 100);
    }

    public get period() {
        return this.options()?.period;
    }

    public get calendar() {
        return this._settings.get('app.group_events_calendar');
    }

    public startPolling(delay = 3 * MINUTES) {
        const poll_delay = Math.max(delay, 3 * MINUTES);
        this.interval(
            'poll',
            () => (document.hasFocus() ? this._poll.set(Date.now()) : ''),
            poll_delay,
        );
        return () => this.stopPolling();
    }

    public stopPolling() {
        this.clearInterval('poll');
    }

    public setOptions(options: Partial<GroupEventOptions>) {
        const current_options = this.options();
        const next_options = { ...current_options, ...options };
        if (this._sameOptions(current_options, next_options)) return;
        this.options.set(next_options);
    }

    private _sameOptions(
        current_options: GroupEventOptions,
        next_options: GroupEventOptions,
    ) {
        return (
            current_options?.period === next_options?.period &&
            current_options?.date === next_options?.date &&
            current_options?.end === next_options?.end &&
            this._sameZoneIds(current_options?.zone_ids, next_options?.zone_ids)
        );
    }

    private _sameZoneIds(zone_ids_a: string[] = [], zone_ids_b: string[] = []) {
        if (zone_ids_a === zone_ids_b) return true;
        if (zone_ids_a.length !== zone_ids_b.length) return false;
        return zone_ids_a.every(
            (zone_id, index) => zone_id === zone_ids_b[index],
        );
    }

    public viewEvent(event: CalendarEvent) {
        const ref = this._dialog.open(GroupEventDetailsModalComponent, {
            ariaLabel: event.title,
            data: {
                event,
                concierge: true,
                edit_fn: (_i) =>
                    this._router.navigate([
                        '/entertainment',
                        'events',
                        'manage',
                        event.id,
                    ]),
                remove_fn: async () => {
                    if (await this.removeEvent(event)) ref.close();
                },
            },
        });
    }

    /** Ask, then remove the event. Resolves true when it was removed. */
    public async removeEvent(event: CalendarEvent): Promise<boolean> {
        const removed = await confirmAction(
            this._dialog,
            {
                title: i18n('APP.CONCIERGE.EVENTS_REMOVE_TITLE'),
                content: i18n('APP.CONCIERGE.EVENTS_REMOVE_MSG', {
                    title: event.title,
                }),
                icon: { content: 'delete' },
                confirm_text: i18n('COMMON.REMOVE'),
            },
            {
                loading: i18n('APP.CONCIERGE.EVENTS_REMOVE_LOADING'),
                action: () =>
                    removeEvent(event.id, { calendar: this.calendar }),
                error: (e) =>
                    i18n('APP.CONCIERGE.EVENTS_REMOVE_ERROR', {
                        error: errorText(e),
                    }),
            },
        );
        if (!removed) return false;
        notifySuccess(i18n('APP.CONCIERGE.EVENTS_REMOVE_SUCCESS'));
        this._changed.set(Date.now());
        return true;
    }
}
